// Pure habitat-code logic (no DOM). Mirror of pipeline/suitability.py:
// tests/vectors.json, generated by Python, keeps both implementations identical.
//
// Tile pixel layout (RGBA):
//   R tree   : 0 pine,1 spruce,2 douglas,3 larch,4 fir,5 beech,6 oak,7 birch,8 alder,
//              9 other,10 canopy loss, 255 no forest
//   G soil   : low nibble nutrient 0..10 (A=2 Z=4 M=6 K=8 R=10, odd = half step),
//              0x10 carbonate, 0x20 peat, 0x40 spoil heap, 0x80 forest edge
//   B water  : low nibble 1 dry .. 8 swampy (0 unknown), 0x10 NSG, 0x20 national park
//   A        : 255 inside Berlin/Brandenburg

export const TREES = ["Pine", "Spruce", "Douglas fir", "Larch", "Fir", "Beech", "Oak",
  "Birch", "Alder", "Other broadleaf", "Clearing / canopy loss"];
export const NUTRIENT = ["unknown", "A poor", "A poor", "A–Z", "Z rather poor", "Z–M",
  "M medium", "M–K", "K rich", "K–R", "R very rich"];
export const WATER = ["unknown", "dry", "moderately fresh", "weakly groundwater-fresh", "fresh",
  "very fresh", "damp", "wet", "swampy"];
export const FLAG = { CARBONATE: 0x10, PEAT: 0x20, SPOIL: 0x40, EDGE: 0x80, NSG: 0x10, NATP: 0x20 };

const LETTERS = ["A", "Z", "M", "K", "R"];

export function nutrientTable(sp) {
  const vals = LETTERS.map((l) => sp.nutrient[l]);
  const t = new Array(11).fill(0);
  for (let i = 1; i <= 10; i++) {
    if (i % 2 === 0) t[i] = vals[i / 2 - 1];
    else if (i === 1) t[i] = vals[0];
    else t[i] = (vals[(i - 1) / 2 - 1] + vals[(i - 1) / 2]) / 2;
  }
  return t;
}

// Precompute lookup tables once per species.
export function compile(sp) {
  const host = new Float32Array(256);
  sp.host.forEach((v, i) => { host[i] = v; });
  const nut = Float32Array.from(nutrientTable(sp));
  const wat = new Float32Array(16);
  sp.water.forEach((v, i) => { wat[i + 1] = v; });
  return { host, nut, wat, unknown: sp.unknown, edge: !!sp.edge };
}

// Suitability in [0,1] for one pixel. Float32 math to match numpy float32.
export function score(c, tree, soil, water) {
  const f = Math.fround;
  const n = soil & 0x0f;
  const w = water & 0x0f;
  const isEdge = (soil & 0x80) !== 0;
  let host = c.host[tree];
  const site = n > 0 && w > 0 ? f(c.nut[n] * c.wat[w]) : f(c.unknown);
  if (c.edge) {
    if (tree === 255) host = isEdge ? f(0.6) : 0;
    host = f(host * (isEdge ? 1 : f(0.35)));
  }
  return f(host * site);
}

// Thresholds compared in float32, like numpy does for a float32 array vs a Python float.
export function classify(s, classes) {
  const f = Math.fround;
  if (s >= f(classes.high)) return 3;
  if (s >= f(classes.medium)) return 2;
  if (s >= f(classes.low)) return 1;
  return 0;
}

// Colours per class: transparent, low, medium, high (sequential, one hue family).
export const CLASS_RGBA = [
  [0, 0, 0, 0],
  [242, 193, 78, 170],
  [228, 118, 28, 215],
  [178, 40, 18, 235],
];

// Colourise a code tile (Uint8ClampedArray RGBA) in place into out (same length).
// Protected areas get a diagonal hatch so the legal status stays visible.
export function colorize(codes, out, compiled, classes, width = 256) {
  for (let i = 0; i < codes.length; i += 4) {
    const a = codes[i + 3];
    let r = 0, g = 0, b = 0, al = 0;
    if (a) {
      const cls = classify(score(compiled, codes[i], codes[i + 1], codes[i + 2]), classes);
      [r, g, b, al] = CLASS_RGBA[cls];
      const prot = codes[i + 2] & 0x30;
      if (prot) {
        const p = i >> 2;
        const x = p % width, y = (p / width) | 0;
        if ((x + y) % 8 < 2) { r = 29; g = 78; b = 216; al = Math.max(al, 200); }
      }
    }
    out[i] = r; out[i + 1] = g; out[i + 2] = b; out[i + 3] = al;
  }
  return out;
}

// Human readable description of one pixel.
export function describe(tree, soil, water) {
  return {
    tree: tree === 255 ? "no forest" : TREES[tree] ?? "?",
    nutrient: NUTRIENT[soil & 0x0f],
    water: WATER[water & 0x0f],
    peat: (soil & FLAG.PEAT) !== 0,
    carbonate: (soil & FLAG.CARBONATE) !== 0,
    edge: (soil & FLAG.EDGE) !== 0,
    nsg: (water & FLAG.NSG) !== 0,
    nationalpark: (water & FLAG.NATP) !== 0,
    siteKnown: (soil & 0x0f) > 0 && (water & 0x0f) > 0,
  };
}

// Web Mercator helpers for click lookups.
export function lngLatToTilePixel(lng, lat, z) {
  const n = 2 ** z;
  const x = ((lng + 180) / 360) * n;
  const latR = (lat * Math.PI) / 180;
  const y = ((1 - Math.log(Math.tan(latR) + 1 / Math.cos(latR)) / Math.PI) / 2) * n;
  const tx = Math.floor(x), ty = Math.floor(y);
  return { tx, ty, px: Math.floor((x - tx) * 256), py: Math.floor((y - ty) * 256) };
}

export function isInSeason(sp, month) {
  const [a, b] = sp.season;
  return a <= b ? month >= a && month <= b : month >= a || month <= b;
}
